<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {completeCompanySocial,CompanySocialError} from './company-social-client';import '../automations/automations.css';
 export let accessSignal:AbortSignal;const dispatch=createEventDispatcher<{resumed:{companyId:string;conversationId:string;draftId:null};denied:{status:number}}>();const controller=new AbortController();let busy=true,error='',receipt:{companyId:string;sourceConversationId:string}|null=null,active=true;
 function stop(){active=false;controller.abort();receipt=null;busy=false;}
 onMount(()=>{accessSignal.addEventListener('abort',stop,{once:true});const fragments=new URLSearchParams(location.hash.slice(1));let handoff=fragments.get('handoff')||'';const valid=fragments.size===1&&fragments.getAll('handoff').length===1&&handoff.length>0&&handoff.length<=512;history.replaceState(history.state,'',location.pathname);if(!valid||accessSignal.aborted){error='Publishing-account sign-in could not be verified. Return to the original company chat and start again.';busy=false;return;}void completeCompanySocial(handoff,controller.signal,()=>localStorage.getItem('token')||'').then(value=>{if(active&&!accessSignal.aborted)receipt=value;}).catch(cause=>{if(!active||accessSignal.aborted)return;if(cause instanceof CompanySocialError&&(cause.status===401||cause.status===403))dispatch('denied',{status:cause.status});error='The sign-in outcome could not be confirmed. Return to the saved company connection and refresh it before starting again.';}).finally(()=>{handoff='';if(active)busy=false;});});onDestroy(()=>{stop();accessSignal.removeEventListener('abort',stop);});
</script>
<section class="starli-automations callback" aria-label="Publishing account sign-in"><span class="sa-eyebrow">STARLI INTEGRATIONS</span><h2>{receipt?'Your publishing account is connected':'Completing secure account sign-in'}</h2>{#if busy}<p class="sa-muted" role="status">Verifying the saved account authorization…</p>{/if}{#if error}<p class="sa-error" role="alert">{error}</p><a class="sa-link" href="/app">Return to Starli</a>{/if}{#if receipt}<p class="sa-muted">This has not granted company publishing access. Return to the original chat to explicitly choose and delegate your Facebook Pages and Instagram accounts.</p><button class="sa-primary" on:click={()=>receipt&&dispatch('resumed',{companyId:receipt.companyId,conversationId:receipt.sourceConversationId,draftId:null})}>Review company destinations</button>{/if}</section>
